const crypto = require('crypto');

function sha256(value) {
  return crypto.createHash('sha256').update(value, 'utf8').digest('hex');
}

function normEmail(email) {
  return String(email || '').trim().toLowerCase();
}

function normPhone(phone) {
  let digits = String(phone || '').replace(/\D/g, '');
  if (!digits) return '';
  if (digits.startsWith('00')) digits = digits.slice(2);
  else if (digits.startsWith('0')) digits = '49' + digits.slice(1);
  return digits;
}

const raw = $input.first().json || {};
const item = (raw.body && typeof raw.body === 'object' && !Array.isArray(raw.body)) ? raw.body : raw;
const headers = raw.headers || {};
const headerSecret = headers['x-n8n-webhook-secret'] || headers['X-N8N-Webhook-Secret'] || '';
const expected = '__N8N_WEBHOOK_SECRET__';
const provided = item.auth_secret || (item.auth && item.auth.secret) || headerSecret || '';

if (!expected || provided !== expected) {
  return [{ json: { ok: false, statusCode: 401 } }];
}

const email = normEmail(item.user?.email);
const phone = normPhone(item.user?.phone);
const emailOk = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);

if (!emailOk) {
  return [{ json: { ok: false, statusCode: 400 } }];
}

const event_id = String(item.event_id || crypto.randomUUID());
const event_time = Number(item.event_time) || Math.floor(Date.now() / 1000);

const meta = {
  event_name: 'Lead',
  event_id,
  event_time,
  action_source: 'website',
  event_source_url: item.event_source_url || item.landing_url,
  user_data: {
    em: [sha256(email)],
    ph: phone ? [sha256(phone)] : [],
    client_ip_address: item.user?.client_ip || undefined,
    client_user_agent: item.user?.user_agent || undefined,
    fbc: item.click_ids?.fbc || undefined,
    fbp: item.click_ids?.fbp || undefined,
  },
  custom_data: {
    content_name: 'Beratung',
    status: 'submitted',
    currency: 'EUR',
    intent: item.details?.intent || undefined,
    place: item.details?.place || undefined,
  },
};

const google = {
  conversion_action: 'Lead',
  conversion_id: event_id,
  gclid: item.click_ids?.gclid || undefined,
  gbraid: item.click_ids?.gbraid || undefined,
  wbraid: item.click_ids?.wbraid || undefined,
};

return [{
  json: {
    ok: true,
    statusCode: 200,
    event_id,
    adapters: {
      meta: { mode: 'dry-run', reason: 'no_ads_token_configured', payload: meta },
      google: { mode: 'dry-run', reason: 'no_ads_token_configured', payload: google },
    },
  },
}];
